# Build local coordinates relative to each nominal 7x7 core; outside entries retain negative or >6 coords.
n=7
pieces={}
# 2 core as described
p2={(r,c) for r in range(7) for c in range(7) if (r,c) not in {(0,2),(3,0),(3,1),(3,2)}} # wait row0 missing index2; row3 missing first3
# explicitly correct
p2={(r,c) for r in range(7) for c in range(7)} - {(0,2),(3,0),(3,1),(3,2)}
# row0 core source c1..7 values c1,2,3 colored; c4 zero => local c3. Correction: core row0 pattern 1110111 means local c3 absent, not c2.
p2={(r,c) for r in range(7) for c in range(7)} - {(0,3),(3,0),(3,1),(3,2)}
#3 core 7x7, holes at local row4,5,6 col3; extension left of core row3
p3={(r,c) for r in range(7) for c in range(7)}-{(4,3),(5,3),(6,3)} | {(3,-1),(3,-2),(3,-3)}
#7 core rows 0..6 cols0..6, missing row3 c0,c1; marker at (6,6); extensions at r=-3..-1,c3
p7={(r,c) for r in range(7) for c in range(7)}-{(3,0),(3,1)} | {(-1,3),(-2,3),(-3,3)}
#8 core full + extensions right at (3,7), down at (7,3),(8,3)
p8={(r,c) for r in range(7) for c in range(7)} | {(3,7),(7,3),(8,3)}
pieces={'2':p2,'3':p3,'7':p7,'8':p8}
{key:len(val) for key,val in pieces.items()}

def placed(piece, ori, q):
    k,f=ori; ro,co=quads[q]
    return {(ro+rr,co+cc) for r,c in piece for rr,cc in [orient_pt((r,c),k,f)]}
def test_combo(ori7, assignments, orientations):
    loc={'7':('TL',ori7)}
    for key,q,ori in zip(['2','3','8'],assignments,orientations): loc[key]=(q,ori)
    allcells=[]
    for key,(q,ori) in loc.items(): allcells.extend(placed(pieces[key],ori,q))
    return len(allcells)==196 and len(set(allcells))==196 and set(allcells)=={(r,c) for r in range(14) for c in range(14)}
solutions=[]
for ori7 in orient7:
    for qs in itertools.permutations(['TR','BL','BR']):
        for os in itertools.product(oris, repeat=3):
            if test_combo(ori7,qs,os):
                solutions.append((ori7,dict(zip(['2','3','8'],zip(qs,os)))))
len(solutions), solutions[:10]

sol1=solutions[0]
loc7={'7':('TL',(2,False))}
loc7.update(sol1[1])
grid=[[0]*14 for _ in range(14)]
for key,(q,ori) in loc7.items():
    col=int(key)
    for r,c in placed(pieces[key],ori,q):
        if grid[r][c]!=0:
            print('collision',key,r,c,grid[r][c])
        grid[r][c]=5 if key=='7' and (r,c) in placed({(6,6)},ori,q) else col
print('\n'.join(' '.join(map(str,row)) for row in grid))
print('zeros',sum(x==0 for row in grid for x in row), 'counts', {x:sum(v==x for row in grid for v in row) for x in set(v for row in grid for v in row)})
